import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class AttendanceService {
  private apiUrl = 'http://localhost:3000/api/attendance';

  constructor(private http: HttpClient) { }

  getAllAttendance(): Observable<any> {
    return this.http.get(`${this.apiUrl}/allattendance`, { withCredentials: true });
  }

  updateAttendance(id: string, data: any): Observable<any> {
    return this.http.put(`${this.apiUrl}/update/${id}`, data, { withCredentials: true });
  }
}
